INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z12-q344','nism-5a-z12','For a scheme with performance history of more than 3 years, advertisements must show CAGR for:','["10 years only","Only the last month","1 and 2 years only","1, 3, 5 years and since inception"]',3,'Plus the point-to-point value of ₹10,000.',344) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z12-q345','nism-5a-z12','For a breach of the AMFI code, AMFI first seeks an explanation from the intermediary within:','["3 days","3 weeks","1 year","3 months"]',1,'A proven second violation leads to ARN cancellation.',345) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
