INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z12-q348','nism-5a-z12','A scheme with average net assets of ₹300 crore incurs total recurring expenses of ₹3.10 crore in a year. Its expense ratio is:','["0.517%","1.023%","1.033%","2.067%"]',2,'TER = 3.10 ÷ 300 × 100 = 1.033%.',348) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
