INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z12-q350','nism-5a-z12','For an interval fund, the minimum transaction period and interval period are respectively:','["1 day and 7 days","3 days and 60 days","2 days and 15 calendar days","5 days and 30 days"]',2,'Transaction period at least 2 days; interval period at least 15 calendar days.',350) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
