INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z12-q353','nism-5a-z12','The Direct plan has a lower expense ratio because it has:','["No exit load","A different benchmark","No distribution cost or commission","A different portfolio"]',2,'It has a separate NAV.',353) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
